// Gestion de la vérification webhook Meta (GET) + messages entrants (POST)
const req = $input.first().json;

// Vérification initiale Meta (requête GET lors de la config)
if (req.query && req.query['hub.mode'] === 'subscribe') {
  const VERIFY_TOKEN = $vars.META_WEBHOOK_VERIFY_TOKEN;
  if (req.query['hub.verify_token'] === VERIFY_TOKEN) {
    return [{ json: { type: 'verification', challenge: req.query['hub.challenge'] } }];
  } else {
    throw new Error('Token de vérification invalide');
  }
}

// Traitement des messages entrants
const body = req.body;
if (!body || !body.entry) {
  return [{ json: { type: 'ignored', reason: 'Pas de body valide' } }];
}

const messages = [];

for (const entry of body.entry) {
  for (const messaging of (entry.messaging || [])) {
    // Ignorer les messages envoyés par nous-mêmes
    if (messaging.message && !messaging.message.is_echo) {
      messages.push({
        json: {
          type: 'dm',
          sender_id: messaging.sender.id,
          recipient_id: messaging.recipient.id,
          timestamp: messaging.timestamp,
          message_text: messaging.message.text || '',
          message_id: messaging.message.mid,
          attachments: messaging.message.attachments || []
        }
      });
    }
  }
}

if (messages.length === 0) {
  return [{ json: { type: 'ignored', reason: 'Aucun DM textuel' } }];
}

return messages;

const claudeResponse = $input.first().json;
const originalDM = $('Extraire le DM').first().json;

// Parser la réponse Claude
const content = claudeResponse.content[0].text;
let analysis;
try {
  analysis = JSON.parse(content);
} catch(e) {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  analysis = JSON.parse(jsonMatch[0]);
}

return [{
  json: {
    // Données originales du DM
    sender_id: originalDM.sender_id,
    message_original: originalDM.message_text,
    timestamp: originalDM.timestamp,
    // Analyse Claude
    reponse_dm: analysis.reponse_dm,
    score_lead: analysis.score_lead,
    persona_detecte: analysis.persona_detecte,
    intention: analysis.intention,
    note_interne: analysis.note_interne,
    // Drapeaux
    lead_chaud: analysis.score_lead >= 7,
    lead_moyen: analysis.score_lead >= 4 && analysis.score_lead < 7,
    hors_sujet: analysis.score_lead < 2
  }
}];
